-- ============================================================================
-- ИСХОДНАЯ СХЕМА ТАБЛИЦ В SQLite (5 ТАБЛИЦ — УРОВЕНЬ EASY)
-- Задача: перевести этот скрипт на диалект PostgreSQL и выполнить в DBeaver!
-- ============================================================================
-- Обратите внимание на особенности SQLite, которые НУЖНО заменить в PostgreSQL:
-- 1. INTEGER PRIMARY KEY AUTOINCREMENT  -->  SERIAL PRIMARY KEY (или GENERATED BY DEFAULT AS IDENTITY)
-- 2. TEXT (для коротких строк с лимитом) -->  VARCHAR(n) (например, VARCHAR(20), VARCHAR(30))
-- 3. REAL (плавающая точка для денег)   -->  NUMERIC(8, 2) или NUMERIC(10, 2)
-- 4. INTEGER DEFAULT 0 / 1 (для флагов) -->  BOOLEAN DEFAULT FALSE / TRUE
-- 5. TEXT (для дат 'YYYY-MM-DD')        -->  DATE

CREATE TABLE tariffs (
    tariff_id INTEGER PRIMARY KEY AUTOINCREMENT,
    zone_name TEXT NOT NULL UNIQUE,
    hourly_rate REAL NOT NULL CHECK (hourly_rate > 0),
    is_vip INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE members (
    member_id INTEGER PRIMARY KEY AUTOINCREMENT,
    nickname TEXT NOT NULL UNIQUE,
    balance REAL NOT NULL DEFAULT 0.0 CHECK (balance >= 0),
    is_verified INTEGER NOT NULL DEFAULT 0,
    reg_date TEXT NOT NULL
);

CREATE TABLE pcs (
    pc_id INTEGER PRIMARY KEY AUTOINCREMENT,
    pc_code TEXT NOT NULL UNIQUE,
    tariff_id INTEGER NOT NULL REFERENCES tariffs(tariff_id),
    ram_gb INTEGER NOT NULL CHECK (ram_gb IN (16, 32, 64)),
    is_active INTEGER NOT NULL DEFAULT 1
);

CREATE TABLE sessions (
    session_id INTEGER PRIMARY KEY AUTOINCREMENT,
    member_id INTEGER REFERENCES members(member_id),
    pc_id INTEGER NOT NULL REFERENCES pcs(pc_id),
    hours INTEGER NOT NULL CHECK (hours > 0 AND hours <= 24),
    session_date TEXT NOT NULL
);

CREATE TABLE bar_orders (
    order_id INTEGER PRIMARY KEY AUTOINCREMENT,
    session_id INTEGER NOT NULL REFERENCES sessions(session_id),
    item_name TEXT NOT NULL,
    price REAL NOT NULL CHECK (price > 0),
    is_delivered INTEGER NOT NULL DEFAULT 0
);

-- 6-я таблица (для уровней Medium и Hard) — замыкает кольцо связей между Игроками и ПК:
CREATE TABLE tournament_entries (
    entry_id INTEGER PRIMARY KEY AUTOINCREMENT,
    member_id INTEGER NOT NULL REFERENCES members(member_id),
    pc_id INTEGER NOT NULL REFERENCES pcs(pc_id),
    game_title TEXT NOT NULL,
    prize REAL CHECK (prize IS NULL OR prize >= 0),
    UNIQUE (member_id, game_title)
);
